<?php
declare(strict_types=1);
if (session_status() !== PHP_SESSION_ACTIVE) { session_name('NOWRD_INSTALL'); session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'),'httponly'=>true,'samesite'=>'Strict']); ini_set('session.use_strict_mode','1'); session_start(); }
header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: DENY'); header('Referrer-Policy: no-referrer');
if (is_file(__DIR__.'/config.php')) {
  $existing = require __DIR__.'/config.php';
  try { $check = new PDO('mysql:host='.$existing['db_host'].';dbname='.$existing['db_name'].';charset=utf8mb4', $existing['db_user'], $existing['db_pass'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]); $n=(int)$check->query('SELECT COUNT(*) FROM users')->fetchColumn(); if ($n>0) { http_response_code(403); exit('NOWRD sudah terpasang. Demi keamanan, hapus install.php dari server.'); } }
  catch(Throwable $e) { /* allow setup repair if config exists but schema is incomplete */ }
}
if (empty($_SESSION['install_csrf'])) $_SESSION['install_csrf']=bin2hex(random_bytes(32));
$error=''; $success=false;
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if (!hash_equals($_SESSION['install_csrf'], $_POST['_csrf']??'')) { $error='Sesi kedaluwarsa. Muat ulang halaman.'; }
 else {
  $host=trim($_POST['db_host']??'localhost'); $dbname=trim($_POST['db_name']??''); $dbuser=trim($_POST['db_user']??''); $dbpass=$_POST['db_pass']??'';
  $site=trim($_POST['site_name']??'NOWRD'); $name=trim($_POST['admin_name']??''); $email=trim($_POST['admin_email']??''); $pass=$_POST['admin_password']??'';
  if (!$host || !preg_match('/^[A-Za-z0-9._:-]{1,190}$/',$host) || !preg_match('/^[A-Za-z0-9_]+$/',$dbname) || !$dbuser || mb_strlen($site)>190 || !$site || mb_strlen($name)>120 || !$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || mb_strlen($email)>190 || mb_strlen($pass)<8) $error='Periksa kembali semua kolom. Nama database hanya boleh berisi huruf, angka, dan garis bawah. Password minimal 8 karakter.';
  else {
   try {
    // Prefer an existing database (works on most shared hosting plans).
    $pdoOptions=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];
    $dbDsn='mysql:host='.$host.';dbname='.$dbname.';charset=utf8mb4';
    try {
      $pdo=new PDO($dbDsn,$dbuser,$dbpass,$pdoOptions);
    } catch (PDOException $dbError) {
      // If the database is missing, try creating it. Do not assume every connection
      // error means the database is missing: verify server-level authentication first.
      try {
        $server=new PDO('mysql:host='.$host.';charset=utf8mb4',$dbuser,$dbpass,$pdoOptions);
      } catch (PDOException $serverError) {
        error_log('NOWRD installer server connection failed: '.$serverError->getMessage()); throw new RuntimeException('Tidak dapat terhubung ke server MySQL. Periksa host, username, password, dan izin pengguna database.');
      }
      try {
        $server->exec('CREATE DATABASE IF NOT EXISTS `'.$dbname.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
        $pdo=new PDO($dbDsn,$dbuser,$dbpass,$pdoOptions);
      } catch (PDOException $createError) {
        // Common on cPanel/shared hosting: database creation is reserved for the control panel.
        error_log('NOWRD installer create database failed: '.$createError->getMessage()); throw new RuntimeException('Database belum tersedia atau hosting menolak pembuatan database otomatis. Buka panel hosting, buat database dan pengguna, hubungkan pengguna ke database dengan hak yang diperlukan, lalu masukkan nama database lengkap beserta prefix hosting. Tabel NOWRD tetap akan dibuat otomatis setelah koneksi berhasil.');
      }
    }
    $pdo->exec("CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS posts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL UNIQUE, excerpt TEXT NULL, seo_title VARCHAR(220) NULL, seo_description VARCHAR(320) NULL, canonical_url VARCHAR(500) NULL, content LONGTEXT NOT NULL, cover_image VARCHAR(500) NULL, status ENUM('draft','in_review','approved','published') NOT NULL DEFAULT 'draft', author_id INT UNSIGNED NULL, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,published_at), CONSTRAINT fk_posts_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ip_hash CHAR(64) NOT NULL, email VARCHAR(190) NOT NULL, attempted_at DATETIME NOT NULL, INDEX idx_login_ip_time (ip_hash, attempted_at), INDEX idx_login_email_time (email, attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, description VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS tags (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS post_categories (post_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, PRIMARY KEY(post_id,category_id), INDEX idx_pc_category(category_id), CONSTRAINT fk_pc_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, CONSTRAINT fk_pc_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS post_tags (post_id INT UNSIGNED NOT NULL, tag_id INT UNSIGNED NOT NULL, PRIMARY KEY(post_id,tag_id), INDEX idx_pt_tag(tag_id), CONSTRAINT fk_pt_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, CONSTRAINT fk_pt_tag FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, original_name VARCHAR(255) NOT NULL, file_name VARCHAR(100) NOT NULL UNIQUE, file_path VARCHAR(500) NOT NULL, mime_type VARCHAR(100) NOT NULL, file_size BIGINT UNSIGNED NOT NULL, width INT UNSIGNED NOT NULL, height INT UNSIGNED NOT NULL, alt_text VARCHAR(300) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_media_created (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $seed=$pdo->prepare('INSERT IGNORE INTO settings(setting_key,setting_value) VALUES (?,?)'); foreach([['site_tagline','A quieter space for ideas.'],['site_description',''],['site_url',''],['accent_color','#b7f36b']] as $s){$seed->execute($s);}
    if ((int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()>0) throw new RuntimeException('Sudah ada akun admin di database ini. Gunakan database kosong agar tidak menimpa akun yang ada.');
    $q=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)'); $q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);
    $config=['db_host'=>$host,'db_name'=>$dbname,'db_user'=>$dbuser,'db_pass'=>$dbpass,'site_name'=>$site,'base_url'=>'','timezone'=>'Asia/Jakarta'];
    $php="<?php\nreturn ".var_export($config,true).";\n";
    if (file_put_contents(__DIR__.'/config.php',$php,LOCK_EX)===false) { $pdo->prepare('DELETE FROM users WHERE email=?')->execute([$email]); throw new RuntimeException('Tidak dapat menulis config.php. Beri izin tulis sementara pada folder NOWRD, lalu ulangi.'); }
    $success=true; session_regenerate_id(true);
   } catch(Throwable $e) { error_log('NOWRD installation failed: '.$e->getMessage()); $error='Instalasi gagal. Periksa kembali konfigurasi database dan izin folder. Jika masalah berlanjut, periksa error log hosting.'; if ($e instanceof RuntimeException && str_contains($e->getMessage(), 'Database belum tersedia')) $error=$e->getMessage(); elseif ($e instanceof RuntimeException && str_contains($e->getMessage(), 'Tidak dapat terhubung')) $error=$e->getMessage(); elseif ($e instanceof RuntimeException && str_contains($e->getMessage(), 'Sudah ada akun admin')) $error=$e->getMessage(); elseif ($e instanceof RuntimeException && str_contains($e->getMessage(), 'config.php')) $error=$e->getMessage(); }
  }
 }
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Instalasi NOWRD</title><style>
:root{color-scheme:light;--ink:#20231f;--muted:#777d75;--line:#e5e8e1;--accent:#b7f36b;--bg:#f6f7f3}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}.wrap{max-width:700px;margin:5vh auto;padding:24px}.brand{font-size:22px;font-weight:850;letter-spacing:-1px;margin:0 0 24px}.mark{display:inline-grid;place-items:center;background:var(--accent);width:32px;height:32px;border-radius:10px;margin-right:8px}.card{background:white;border:1px solid var(--line);border-radius:22px;padding:clamp(22px,5vw,42px);box-shadow:0 15px 45px #20231f08}h1{font-size:clamp(30px,5vw,42px);line-height:1.08;letter-spacing:-1.7px;margin:8px 0 12px}.intro{color:var(--muted);margin:0 0 28px}.step{font-size:11px;text-transform:uppercase;letter-spacing:1.7px;font-weight:800;color:#697164}fieldset{border:0;padding:0;margin:26px 0 0}legend{font-weight:800;font-size:17px;margin-bottom:14px;letter-spacing:-.3px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:13px;font-weight:700;margin:0 0 7px}input{width:100%;border:1px solid #dfe3db;border-radius:10px;padding:12px 13px;font:inherit;outline:none;background:#fff}input:focus{border-color:#8cbf49;box-shadow:0 0 0 3px #b7f36b38}.field{margin-bottom:15px}.hint{font-size:12px;color:var(--muted);margin-top:6px}.meter{height:5px;background:#ecefe8;border-radius:9px;overflow:hidden;margin-top:9px}.meter span{display:block;width:0;height:100%;transition:width .2s,background .2s}.strength{font-size:12px;font-weight:700;margin-top:5px;color:#858b80}.button{width:100%;border:0;border-radius:12px;background:var(--ink);color:#fff;font-weight:800;font-size:15px;padding:15px;cursor:pointer;margin-top:24px}.alert{padding:13px 15px;border-radius:10px;background:#fff0ed;color:#a52d1b;margin:18px 0}.success{background:#effbe3;border:1px solid #d5edbd;border-radius:14px;padding:17px;margin:20px 0}.foot{font-size:12px;color:var(--muted);text-align:center;margin-top:20px}@media(max-width:560px){.wrap{margin:0 auto;padding:18px 13px}.grid{grid-template-columns:1fr;gap:0}.card{border-radius:17px}}
</style></head><body><div class="wrap"><div class="brand"><span class="mark">n.</span>NOWRD</div><main class="card"><div class="step">SETUP WIZARD · INSTALASI OTOMATIS</div><h1><?= $success?'NOWRD siap digunakan.':'Mari siapkan website Anda.' ?></h1><p class="intro"><?= $success?'Database dan akun administrator berhasil disiapkan.':'Masukkan detail database dan buat akun administrator. Struktur tabel akan dibuat otomatis.' ?></p>
<?php if($error): ?><div class="alert"><?=h($error)?></div><?php endif; ?>
<?php if($success): ?><div class="success"><strong>Instalasi berhasil!</strong><br>Untuk keamanan, segera hapus file <code>install.php</code> dari hosting. Halaman admin tidak ditautkan dari website publik.<br><br><a href="admin/login.php">Buka halaman login admin →</a></div><?php else: ?>
<form method="post" autocomplete="on"><input type="hidden" name="_csrf" value="<?=h($_SESSION['install_csrf'])?>"><fieldset><legend>01 — Konfigurasi database</legend><div class="grid"><div class="field"><label for="db_host">Database host</label><input id="db_host" name="db_host" maxlength="190" value="<?=h($_POST['db_host']??'localhost')?>" required></div><div class="field"><label for="db_name">Nama database</label><input id="db_name" name="db_name" value="<?=h($_POST['db_name']??'nowrd')?>" pattern="[A-Za-z0-9_]+" maxlength="64" required></div><div class="field"><label for="db_user">Database username</label><input id="db_user" name="db_user" value="<?=h($_POST['db_user']??'')?>" required autocomplete="username"></div><div class="field"><label for="db_pass">Database password</label><input id="db_pass" name="db_pass" type="password" autocomplete="new-password"></div></div><p class="hint">Wizard mencoba memakai database yang sudah ada terlebih dahulu. Jika belum ada, wizard akan mencoba membuatnya otomatis. Pada shared hosting yang membatasi izin CREATE DATABASE, buat database dan pengguna melalui panel hosting, beri pengguna hak ALL PRIVILEGES, lalu masukkan nama database lengkap (termasuk prefix akun). Tabel NOWRD tetap dibuat otomatis.</p></fieldset><fieldset><legend>02 — Identitas website</legend><div class="field"><label for="site_name">Nama website</label><input id="site_name" name="site_name" maxlength="190" value="<?=h($_POST['site_name']??'NOWRD')?>" required></div></fieldset><fieldset><legend>03 — Akun administrator</legend><div class="grid"><div class="field"><label for="admin_name">Nama administrator</label><input id="admin_name" name="admin_name" maxlength="120" value="<?=h($_POST['admin_name']??'')?>" required autocomplete="name"></div><div class="field"><label for="admin_email">Email</label><input id="admin_email" name="admin_email" type="email" maxlength="190" value="<?=h($_POST['admin_email']??'')?>" required autocomplete="email"></div></div><div class="field"><label for="admin_password">Kata sandi <span style="color:#7c8278;font-weight:500">(minimal 8 karakter)</span></label><input id="admin_password" name="admin_password" type="password" minlength="8" required autocomplete="new-password" aria-describedby="strengthText"><div class="meter"><span id="meterBar"></span></div><div class="strength" id="strengthText">Masukkan kata sandi · minimal 8 karakter</div><div class="hint">Boleh lebih panjang. Gunakan kombinasi huruf besar, huruf kecil, angka, dan simbol.</div></div></fieldset><button class="button" type="submit">Pasang NOWRD secara otomatis ↗</button></form><?php endif; ?></main><div class="foot">NOWRD CMS · Setup aman melalui wizard</div></div><script>const pw=document.getElementById('admin_password'),bar=document.getElementById('meterBar'),txt=document.getElementById('strengthText');if(pw){pw.addEventListener('input',()=>{const s=pw.value;let score=0;if(s.length>=8)score++;if(s.length>=12)score++;if(/[a-z]/.test(s)&&/[A-Z]/.test(s))score++;if(/[0-9]/.test(s))score++;if(/[^A-Za-z0-9]/.test(s))score++;const labels=['Sangat lemah','Lemah','Cukup','Kuat','Sangat kuat'];const colors=['#dc4c43','#ed8b36','#d6b72f','#70b84a','#25965b'];const level=s.length===0?-1:Math.min(4,Math.max(0,score-1));bar.style.width=s.length?((level+1)*20)+'%':'0';bar.style.background=colors[Math.max(0,level)];txt.textContent=s.length===0?'Masukkan kata sandi · minimal 8 karakter':(s.length<8?'Belum memenuhi minimal 8 karakter · ':'')+labels[level];txt.style.color=s.length<8?'#dc4c43':colors[level];});}</script></body></html>
